use std::fs
use std::process

fn fail() {
    println("error")
    process::exit(1)
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let lines: Vec<string> = text.lines().collect()
    if lines.len() < 1 {
        fail()
        return
    }
    let head: Vec<string> = lines[0].split_whitespace().map(|x| x.to_string()).collect()
    if head.len() != 2 {
        fail()
        return
    }
    let r = head[0].parse::<int>().unwrap_or(0)
    let c = head[1].parse::<int>().unwrap_or(0)
    if r < 1 || c < 1 {
        fail()
        return
    }
    let mut grid: Vec<Vec<int>> = []
    let mut i: int = 0
    while i < r {
        let idx = (i + 1) as usize
        if idx >= lines.len() {
            fail()
            return
        }
        let parts: Vec<string> = lines[idx].split_whitespace().map(|x| x.to_string()).collect()
        if parts.len() as int != c {
            fail()
            return
        }
        let mut row: Vec<int> = []
        for p in parts {
            match p.parse::<int>() {
                Ok(v) => row.push(v),
                Err(_) => {
                    fail()
                    return
                }
            }
        }
        grid.push(row)
        i += 1
    }
    let mut out: Vec<string> = []
    let mut top: int = 0
    let mut bot: int = r - 1
    let mut left: int = 0
    let mut right: int = c - 1
    while top <= bot && left <= right {
        let mut j = left
        while j <= right {
            out.push("${grid[top as usize][j as usize]}")
            j += 1
        }
        top += 1
        let mut k = top
        while k <= bot {
            out.push("${grid[k as usize][right as usize]}")
            k += 1
        }
        right -= 1
        if top <= bot {
            let mut j2 = right
            while j2 >= left {
                out.push("${grid[bot as usize][j2 as usize]}")
                j2 -= 1
            }
            bot -= 1
        }
        if left <= right {
            let mut k2 = bot
            while k2 >= top {
                out.push("${grid[k2 as usize][left as usize]}")
                k2 -= 1
            }
            left += 1
        }
    }
    println(out.join(" "))
}

